const a5b = new THREE.Vector4(M04.num('m04a5w', 1.3), M04.num('m04a5s', 2.2), 0, M04.num('m04a5d', 30));
const nbU = new THREE.Vector4(M04.num('m04nband', 0) > 0 && M04.num('m04sband', 0) > 0 ? 1 : 0, 0, 0, M04.num('m04nbh', 1.1));
const nwOn = nbU.x > 0 && M04.num('m04nwhirl', 0) > 0;   // r18 m04nwhirl (needs m04nband)
const MwInv = Mw.clone().invert();
if (M04.river) {
  const nX = 28, nA = Math.ceil(len / 0.5);
  const pos: number[] = [], aR: number[] = [], idx: number[] = [];
  // r19b m04wup: the trough edge then ends a hair IN FRONT of the flattened lower wall (r + 0.05; m04wug u inside it) instead
  // of 0.03 u behind it, so no sliver of gold wall shows between the river and the water climbing the wall near the camera
  const wup = M04.num('m04wup', 0) > 0;
  const Rt = wup ? r + 0.05 - M04.num('m04wug', 0.1) : r + 0.08;
  const xWr = wup ? Math.sqrt(Math.max(0, Rt * Rt - (cy - RY) ** 2)) : xW;
  // cross-section: flat lane |x| <= XF (a hair above the old water plane), then sides curving up to the wall
  const xs: { x: number; y: number }[] = [];
  for (let i = 0; i <= nX; i++) {
    const u = (i / nX) * 2 - 1, au = Math.abs(u);
    const kf = 0.45; // share of the half section that is the flat lane
    let x: number, y: number;
    if (au <= kf) { x = (au / kf) * XF; y = 0.02; } else { const t = (au - kf) / (1 - kf); x = XF + (xWr - XF) * t; y = 0.02 + RY * t * t; }
    xs.push({ x: Math.sign(u) * x, y });
  }
  const arc: number[] = [0]; const mid = nX / 2;
  for (let i = mid + 1; i <= nX; i++) arc[i] = (arc[i - 1] ?? 0) + Math.hypot(xs[i].x - xs[i - 1].x, xs[i].y - xs[i - 1].y);
  arc[mid] = 0; for (let i = mid - 1; i >= 0; i--) arc[i] = arc[i + 1] - Math.hypot(xs[i].x - xs[i + 1].x, xs[i].y - xs[i + 1].y);
  // from BEHIND (aB u before the opening, where the camera starts) to the far end; before the opening the river
  // lies flat (no wall to climb), the sides rise over the first 2 u inside the tunnel
  const aB = M04.num('m04rb', 14);
  const nT = nA + Math.ceil(aB / 0.5);
  for (let j = 0; j <= nT; j++) {
    const a = -aB + (j / nT) * (len + aB);
    const k = THREE.MathUtils.smoothstep(a, -0.6, 1.4);
    for (let i = 0; i <= nX; i++) { pos.push(cx + xs[i].x, 0.02 + (xs[i].y - 0.02) * k, z0 - a); aR.push(arc[i], 0); }
  }
  for (let j = 0; j < nT; j++) for (let i = 0; i < nX; i++) {
    const p0 = j * (nX + 1) + i, p1 = p0 + 1, p2 = p0 + nX + 1, p3 = p2 + 1;
    idx.push(p0, p2, p1, p1, p2, p3);
  }
  // r19b `&m04wup=1`: the water CLIMBING THE WALL (see RIVER_FRAG / CLIMB): per row, nE more points on each side going up
  // the wall circle from the old water edge (moving a hair in front of the flattened lower wall, below the ring beads),
  // ramped in from m04wua0 to m04wua1 u inside the opening. They share the river's vertex buffer (so the m04rfew
  // telescope shrinks them with the river) but are drawn by their own see-through mesh (soft lapping top edge).
  const idxUp: number[] = [];
  const wuH = Math.min(1.8, M04.num('m04wuh', 1.7));      // highest climb (arc u above the old edge; the wall is flat below ~1.8)
  if (wup) {
    const nE = 12, base = pos.length / 3, W = nE + 1;
    const a0 = M04.num('m04wua0', 1.4), a1 = M04.num('m04wua1', 4.0);
    const th0 = Math.atan2(xWr, cy - RY);                   // the trough edge angle (from straight down) on its circle Rt
    for (let j = 0; j <= nT; j++) {
      const a = -aB + (j / nT) * (len + aB);
      const k2 = THREE.MathUtils.smoothstep(a, a0, a1), k = THREE.MathUtils.smoothstep(a, -0.6, 1.4);
      for (let i = 0; i <= nX; i++) aR[(j * (nX + 1) + i) * 2 + 1] = k2;   // the trough knows the ramp too (top edge, bands)
      for (const sd of [-1, 1]) {
        const ex = cx + sd * xWr, ey = 0.02 + (RY - 0.02) * k;           // this row's trough edge point
        for (let e = 0; e <= nE; e++) {
          const s = (wuH * e) / nE, th = th0 + s / Rt;
          const px = cx + sd * Rt * Math.sin(th), py = cy - Rt * Math.cos(th);
          pos.push(ex + (px - ex) * k2, ey + (py - ey) * k2, z0 - a);
          aR.push(sd * (arc[nX] + s * k2), k2);
        }
      }
    }
    for (let j = 0; j < nT; j++) for (let sI = 0; sI < 2; sI++) for (let e = 0; e < nE; e++) {
      const p0 = base + (j * 2 + sI) * W + e, p1 = p0 + 1, p2 = p0 + 2 * W, p3 = p2 + 1;
      idxUp.push(p0, p2, p1, p1, p2, p3);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('aR', new THREE.Float32BufferAttribute(aR, 2));
  g.setIndex(idx);
  const riv = new THREE.TextureLoader().load(new URL('../../assets/textures/match04/tile_river3.png', import.meta.url).href, (t) => { t.needsUpdate = true; });
  riv.colorSpace = THREE.NoColorSpace; riv.flipY = false; riv.wrapS = riv.wrapT = THREE.RepeatWrapping;
  riv.minFilter = THREE.LinearMipmapLinearFilter; riv.anisotropy = 8;
  let sideBand: THREE.Texture | null = null;
  if (M04.num('m04sband', 0) > 0) {
    sideBand = new THREE.TextureLoader().load(new URL('../../assets/textures/match04/tile_side04.png', import.meta.url).href, (t) => { t.needsUpdate = true; });
    sideBand.colorSpace = THREE.NoColorSpace; sideBand.flipY = false; sideBand.wrapS = THREE.ClampToEdgeWrapping; sideBand.wrapT = THREE.RepeatWrapping;
    sideBand.minFilter = THREE.LinearMipmapLinearFilter; sideBand.anisotropy = 8;
  }
  // tiles04.json river3: lateral +-4 u, along 1.757 .. 6.409 u from Benny's checkpoint water point
  const rm = new THREE.ShaderMaterial({ vertexShader: RIVER_VERT, fragmentShader: RIVER_FRAG, side: THREE.DoubleSide, fog: false,
    extensions: { derivatives: true } as never, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4,
    uniforms: { uPlate: shared.uPlate, uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uProjVP: shared.uProjVP, uAway: away,
      uRiv: { value: riv }, uRivA: { value: new THREE.Vector4(4, 1.7572621, 4.6517529, M04.num('m04rk', 1.0)) }, uTime: time,
      uArr: { value: new THREE.Vector4(M04.num('m04ap', 5.6), 9.58, M04.num('m04aw', 1.0), M04.num('m04at', 0.21)) }, uZ0: { value: z0 },
      uLane: { value: new THREE.Vector3(M04.num('m04lane', 0), M04.num('m04lanew', 1.9), M04.num('m04lanes', 0.85)) },
      uLane3: { value: new THREE.Vector2(M04.num('m04lcd', 0), M04.num('m04lcw', 1.6)) },
      uLane4: { value: (() => { const s = (new URLSearchParams(location.search).get('m04lcn') ?? '').split(',').map(Number);
        return s.length === 2 && s.every(Number.isFinite) ? new THREE.Vector2(s[0], s[1]) : new THREE.Vector2(0, 0); })() },
      uLane2: { value: new THREE.Vector4(M04.num('m04lane2', 0), M04.num('m04lgl', 1.0), M04.num('m04lsp', 0.9), M04.num('m04lbr', 0)) },
      uEdge: { value: new THREE.Vector4(M04.num('m04edge', 0), arc[nX], M04.num('m04edgew', 0.45), M04.num('m04edges', 0.8)) },
      uSE: { value: new THREE.Vector2(M04.num('m04rse', 1), M04.num('m04rsl', 1.2)) },
      uPk: { value: new THREE.Vector4(M04.pink ? 1 : 0, M04.num('m04pkl', 1.05), M04.num('m04pko', 3.6), M04.num('m04pkw', 0.85)) },
      uPkH: { value: M04.num('m04pkh', 0) },
      // r15 `&m04sband=1`: painted swirl bands on the side water (m04sbs strength, m04sbi inner arc, m04sbl tile length u,
      // m04sbw inner blend width, m04sbf 1 = keep the lilac-white edge fringe on top, m04sbu tile part, m04sbn wander,
      // m04sbd0 / m04sbd1 far smoothing window ahead of the camera)
      // r16 defaults (= variant D, chosen by eye at f06 / t66 / hard right): bands from 2.0 u across, the cyan..pink part of the
      // tile (0.7), 10 u long satin stripes with a slow 0.5 u lateral wander, 0.95 strength
      uSB: { value: sideBand }, uSB1: { value: new THREE.Vector4(M04.num('m04sbw', 0.45), M04.num('m04sbf', 1), M04.num('m04sbu', 0.7), M04.num('m04sbn', 0.5)) },
      uSB2: { value: new THREE.Vector2(M04.num('m04sbd0', 0), M04.num('m04sbd1', 0)) },
      // r17 `&m04nband=1` (needs m04sband): the bands round Benny — m04nbh inner arc hugging him, m04nba back to normal this far
      // ahead of him, m04nbb widening behind him (b * d^2), m04nbr half-stripe width near him (0 = one stretched band), m04nbs tile
      // span walked, m04nbp pinch at his sides, m04nbf lateral follow of Benny (0..1)
      uNB3: { value: new THREE.Vector2(M04.num('m04nbr', nwOn ? 1.3 : 0.9), M04.num('m04nbs', 0.7)) },   // r18: broader stripes with the whirl
      // r18 `&m04nwhirl=1` (needs m04nband): the bands wrap round Benny — m04nwk along squash of the ellipse behind him (the
      // nearest stripe closes under him m04nbh / m04nwk u behind), m04nwe its centre ahead of him, m04nwm / m04nwl S-meander
      // amplitude / wavelength of the band edge ahead (0 = off)
      uNB4: { value: new THREE.Vector4(nwOn ? M04.num('m04nwk', 0.5) : 0, M04.num('m04nwe', 0.3), nwOn ? M04.num('m04nwm', 0.35) : 0,
        M04.num('m04nwl', 7)) },
      uNB5: { value: M04.num('m04nwt', 1) },   // m04nwt spiral twist (0 = closed U rings)
      // m04nwc / m04nwcs: cyan corridor straight behind Benny (half width, soft edge; m04nwc=0 = off, the r18 step-3 look)
      uNB6: { value: new THREE.Vector2(nwOn ? M04.num('m04nwc', 0) : 0, M04.num('m04nwcs', 0.8)) },
      // m04nwq=1: clean lane water in the bare parts of the whirl; m04nwr=R: whirl only within R u of Benny (0 = unlimited)
      uNB7: { value: new THREE.Vector2(nwOn ? M04.num('m04nwq', 0) : 0, nwOn ? M04.num('m04nwr', 0) : 0) },
      // r18 `&m04sswirl=1` (needs m04sband): m04ssa swing of the bank ribbons (u), m04ssl its wavelength, m04ssz lapping top
      // edge depth (u, 0 = straight edge), m04ssw lap wavelength
      uSS: { value: M04.num('m04sswirl', 0) > 0 && M04.num('m04sband', 0) > 0
        ? new THREE.Vector4(M04.num('m04ssa', 0.45), M04.num('m04ssl', 6.5), M04.num('m04ssz', 0.0), M04.num('m04ssw', 3.2))
        : new THREE.Vector4(0, 1, 0, 1) },
      // r19b `&m04wup=1` (needs m04sband): m04wuh highest climb (u up the wall), m04wul tongue wavelength, m04wud tongue
      // depth, m04wub band share at the old edge, m04wun0 / m04wun1 / m04wuf the climb falls to m04wuf of it from m04wun0
      // to m04wun1 u ahead of Benny, m04wus soft top edge, m04wuv tongue drift with the current, m04wut band column at the crest, m04wuw crest lace
      uWU: { value: wup ? new THREE.Vector4(wuH, M04.num('m04wul', 9), M04.num('m04wud', 0.35), M04.num('m04wub', 0.6)) : new THREE.Vector4(0, 1, 0, 1) },
      uWU2: { value: new THREE.Vector4(M04.num('m04wun0', 2), M04.num('m04wun1', 14), M04.num('m04wuf', 0.3), M04.num('m04wus', 0.6)) },
      // r20 `&m04wcr=1` (with m04wup): crisp glossy wall swirls — m04wcr strength, m04wcn bands per u up the wall, m04wch
      // highlight lines, m04wcv dark violet edges, m04wcl glossy lip under the crest, m04wcs soft top width (u)
      uWC: { value: new THREE.Vector4(wup ? M04.num('m04wcr', 0) : 0, M04.num('m04wcn', 2.2), M04.num('m04wch', 0.8), M04.num('m04wcv', 0.55)) },
      uWC2: { value: new THREE.Vector2(M04.num('m04wcl', 0.6), M04.num('m04wcs', 0.25)) },
      // r21 `&m04wgl=1` (with m04wup): crisp glossy satin wall water — m04wgl strength, m04wgn ribbons per u up the wall, m04wgh
      // white highlight streaks, m04wgs glints; m04wge crisp top edge (u), m04wgp bright lip, m04wgt translucent lilac top share,
      // m04wgc cyan streak share low down; m04wga / m04wgw ribbon waviness (u) / wavelength (u), m04wgk crease, m04wgo top alpha
      uWG: { value: new THREE.Vector4(wup ? M04.num('m04wgl', 0) : 0, M04.num('m04wgn', 2.2), M04.num('m04wgh', 0.85), M04.num('m04wgs', 0.8)) },
      uWG2: { value: new THREE.Vector4(M04.num('m04wge', 0.04), M04.num('m04wgp', 0.7), M04.num('m04wgt', 0.25), M04.num('m04wgc', 0.35)) },
